#pragma once

// Backpack tiers, recipes, colours and presentation (U1, reworked to Sophisticated Backpacks'
// rules by P2-12).
//
// - Recipes live in the behavior pack (assets/pack/bp/recipes/, generated by
//   tools/recipes/recipes.ps1) and follow SB's table: Leather is crafted, Copper / Iron / Gold /
//   Diamond are "metal around the previous tier" (Iron also " I /IBI/ I " around Copper), Netherite
//   is a smithing-table upgrade of the Diamond backpack.
// - Crafting hooks (TierCrafting.cpp) make a crafted backpack the same backpack as the consumed one
//   (uuid + every bit of item user data: colours, name, upgrades travel with the uuid), and copy
//   the consumed upgrade's data into "next tier" upgrades (Advanced Pickup from Pickup, ...).
//   `Storage::forItem` grows the storage when the item's tier is higher than the stored one.
// - Dyeing (SB `backpack_dye`): one backpack + 1..8 dyes anywhere in the grid. Dyes in columns at
//   or left of the backpack feed the main colour, at or right of it the accent colour, mixed with
//   SC `ColorHelper.calculateColor`. The 16 dyes match the item tag `alleviatedbackpacks:dye`
//   (DyeTag.cpp), which the dye recipes use.
// - Colours live on the item (user data `abp_main_color` / `abp_accent_color`, ARGB ints; absent =
//   SB default) and are mirrored into the bound storage entry (`BackpackData::mainColor/
//   accentColor`) so screens and renderers of carried / placed backpacks see them.
// - Creative inventory (CreativeItems.cpp): after the plain Backpack (Leather), SB's 16 dye
//   variants and the yellow+lime / blue+black one.
// - TierLore.cpp removes the phase-1 lore (SB backpacks have none; `buildLore` stays for that
//   migration) and keeps the item tint (main colour, via the `minecraft:dyeable` item component) in sync.

#include <cstdint>
#include <memory>
#include <optional>
#include <string>
#include <string_view>
#include <vector>

#include "core/Tier.h"

class ItemStack;
class ItemStackBase;
class Player;

namespace abp::game {
class Backpack;
}

namespace abp::tiers {

// ---- colours --------------------------------------------------------------------------------

/// Item user-data keys of a backpack's colours (int, ARGB bits).
inline constexpr std::string_view kMainColorKey   = "abp_main_color";
inline constexpr std::string_view kAccentColorKey = "abp_accent_color";

/// Item tag the dye recipes use for "any of the 16 dyes".
inline constexpr std::string_view kDyeTag = "alleviatedbackpacks:dye";

struct BackpackColors {
    std::uint32_t main;   ///< ARGB
    std::uint32_t accent; ///< ARGB
    [[nodiscard]] bool operator==(BackpackColors const&) const = default;
};

/// SB's defaults (main 0xCC613A, accent 0x622E1A).
[[nodiscard]] BackpackColors defaultColors();
/// The colours stored on the item, or nullopt when it carries none.
[[nodiscard]] std::optional<BackpackColors> itemColors(ItemStackBase const& stack);
/// The colours of a backpack item: the item's, else (legacy items) the bound storage's, else SB's
/// defaults.
[[nodiscard]] BackpackColors colorsOf(ItemStackBase const& stack, game::Backpack const* backpack);
/// Stores `colors` on the item (keeps other user data). Doesn't touch the tint (see refreshItem).
void setItemColors(ItemStackBase& stack, BackpackColors colors);

// ---- presentation ---------------------------------------------------------------------------

/// User-data key holding the colour (0xRRGGBB, -1 = none) we last tinted the item with. Lets the
/// refresher tell its own tint from a cauldron dye/wash done by the player.
inline constexpr std::string_view kTintKey = "abp_tint";

/// The lore lines for a backpack of `tier` (`backpack` may be null for a never-opened backpack),
/// in `player`'s language.
[[nodiscard]] std::vector<std::string> buildLore(Player const& player, core::Tier tier, game::Backpack const* backpack);

/// Translated colour label: the dye name if it is a dye colour, else "#RRGGBB".
[[nodiscard]] std::string colorLabel(Player const& player, std::uint32_t argb);

/// Brings `stack` (a backpack item) up to date: colours (item <-> storage), lore, and the tint
/// (main colour). A cauldron dye or wash on the item since our last tint is adopted as the new
/// main colour first. Returns true if the stack changed (the caller writes it back).
bool refreshItem(Player const& player, ItemStack& stack, std::shared_ptr<game::Backpack> const& backpack);

/// Applies the main colour of `colors` as the item tint (and records it as ours). Returns true if
/// the stack changed.
bool applyTint(ItemStackBase& stack, BackpackColors colors);

/// Refreshes every backpack the player carries (skipped while one of our menus is open).
/// Returns how many items were rewritten.
int refreshPlayer(Player& player);

// ---- crafting -------------------------------------------------------------------------------

/// One item consumed by a craft. `slot` is the PlayerUISlot index of the input slot when
/// `inGrid` (consumed from the crafting input grid); recipe-book crafts may consume straight from
/// the inventory (`inGrid` false: no position).
struct ConsumedInput {
    int                        slot = -1;
    std::shared_ptr<ItemStack> item;
    bool                       inGrid = true;
};

/// Row-major index of a crafting input slot in a 3-wide grid (2x2 slots map to their 3x3
/// position), or -1 for slots outside the crafting grid.
[[nodiscard]] int craftGridIndex(int uiSlot);

/// What a craft does to a backpack.
struct BackpackCraft {
    std::shared_ptr<ItemStack> source;     ///< the consumed backpack
    std::vector<std::uint32_t> mainDyes;   ///< dye colours feeding the main colour
    std::vector<std::uint32_t> accentDyes; ///< dye colours feeding the accent colour
    [[nodiscard]] bool         dyes() const { return !mainDyes.empty() || !accentDyes.empty(); }
};

/// Looks at the consumed inputs: exactly one backpack -> its plan. nullopt otherwise. Dyes are
/// sorted by column (SB): a dye whose position is unknown counts as in the backpack's column.
[[nodiscard]] std::optional<BackpackCraft> analyse(std::vector<ConsumedInput> const& inputs);

/// The colours a craft gives (SC `calculateColor` on the source's current colours).
[[nodiscard]] BackpackColors craftedColors(BackpackCraft const& craft);

/// Makes `result` (a crafted backpack) the same backpack as `craft.source`: copies the source's
/// user data (uuid, name, colours; upgrades travel with the uuid) and, for a dye craft, writes the
/// new colours (+ tint). Returns the uuid bound (may be empty: never-opened backpacks get one on
/// first open).
std::string carryOver(ItemStackBase& result, BackpackCraft const& craft);

/// Mirrors a dye craft's colours into the stored backpack `uuid`. Returns false if there is
/// nothing to do or it can't be loaded.
bool commitColors(std::string const& uuid, BackpackCraft const& craft);

/// SB's creative-tab colour variants of the Backpack (16 dyes, then yellow+lime / blue+black) and
/// the stacks made from them.
[[nodiscard]] std::vector<BackpackColors> creativeColorVariants();
[[nodiscard]] std::vector<ItemStack>      creativeBackpackVariants();

/// SC `upgrade_next_tier` recipes: whether crafting `resultItemId` from the upgrade item
/// `sourceItemId` keeps the source's data (settings).
[[nodiscard]] bool isNextTierUpgrade(std::string_view sourceItemId, std::string_view resultItemId);

} // namespace abp::tiers
